import { useEffect, useState } from "react";

const API_STUDENTS = "http://localhost:5000/students";
const API_COURSES = "http://localhost:5000/courses";
const API_REGISTRATIONS = "http://localhost:5000/registrations";

export default function Registrations() {
  const [students, setStudents] = useState([]);
  const [courses, setCourses] = useState([]);
  const [registrations, setRegistrations] = useState([]);
  const [form, setForm] = useState({ studentId: "", courseId: "", semester: "" });
  const [error, setError] = useState("");

  // Load students, courses, registrations
  useEffect(() => {
    fetch(API_STUDENTS).then((res) => res.json()).then(setStudents);
    fetch(API_COURSES).then((res) => res.json()).then(setCourses);
    fetch(API_REGISTRATIONS).then((res) => res.json()).then(setRegistrations);
  }, []);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch("http://localhost:5000/registrations", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Failed to add registration");

      setRegistrations([...registrations, data.registration]);
      setForm({ studentId: "", courseId: "", semester: "" });
    } catch (err) {
      setError(err.message);
    }
  };

  return (
    <div className="container mt-4">
      <h2>Student Registrations</h2>

      {error && <div className="alert alert-danger">{error}</div>}

      <form onSubmit={handleSubmit} className="row g-2 mb-4">
        <div className="col-md-3">
          <select
            className="form-select"
            name="studentId"
            value={form.studentId}
            onChange={handleChange}
            required
          >
            <option value="">Select Student</option>
            {students.map((s) => (
              <option key={s._id} value={s._id}>{s.name}</option>
            ))}
          </select>
        </div>

        <div className="col-md-3">
          <select
            className="form-select"
            name="courseId"
            value={form.courseId}
            onChange={handleChange}
            required
          >
            <option value="">Select Course</option>
            {courses.map((c) => (
              <option key={c._id} value={c._id}>{c.name}</option>
            ))}
          </select>
        </div>

        <div className="col-md-3">
          <input
            type="text"
            className="form-control"
            name="semester"
            placeholder="Semester/Year"
            value={form.semester}
            onChange={handleChange}
            required
          />
        </div>

        <div className="col-md-3">
          <button type="submit" className="btn btn-primary">Register Student</button>
        </div>
      </form>

      <table className="table table-striped">
        <thead>
          <tr>
            <th>#</th>
            <th>Student Name</th>
            <th>Course Name</th>
            <th>Semester/Year</th>
          </tr>
        </thead>
        <tbody>
          {registrations.map((r, idx) => (
            <tr key={r._id}>
              <td>{idx + 1}</td>
              <td>{r.student.name}</td>
              <td>{r.course.name}</td>
              <td>{r.semester}</td>
            </tr>
          ))}
          {registrations.length === 0 && (
            <tr>
              <td colSpan="4" className="text-center text-muted">No registrations yet</td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}
